/*commonMdCmBasePriceApproval.updateBasePriceReqHdStatus*/
UPDATE KEPMGPHD
   SET STATUS          = #{STATUS}
     , CONFIRM_DATE    = SYSDATE
     , CONFIRM_USER_ID = #{USER_ID}
     , CHANGE_DATE     = SYSDATE
 WHERE BUYER = #{KEY_2}
   AND PM_NO = #{KEY_1}
   AND STATUS = 'C'


/*commonMdCmBasePriceApproval.updateBasePriceReqDtStatus*/
UPDATE KEPMGPDT
   SET STATUS          = #{STATUS}
     , CONFIRM_DATE    = SYSDATE
     , CONFIRM_USER_ID = #{USER_ID}
     , CHANGE_DATE     = SYSDATE
 WHERE BUYER = #{KEY_2}
   AND PM_NO = #{KEY_1}


/*commonMdCmBasePriceApproval.updateBasePriceApply*/
UPDATE CMSCATLG
   SET BASE_PRICE      = TO_NUMBER(F_HST_CMSCATLG(CMS_CATLG_ID
                                                , 'BASE_PRICE'
                                                , #{CH_BASE_PRICE}
                                                , #{USER_ID}
                                                , #{BASE_PRICE_CHANGE_REASON}
                                                , #{CH_BASE_PRICE_TYPE_NM}
                                                , NULL))
     , BASE_PRICE_TYPE = #{CH_BASE_PRICE_TYPE}
     , CHANGE_USER_ID  = #{USER_ID}
     , CHANGE_DATE     = TO_CHAR(SYSDATE,'YYYYMMDD')
     , CHANGE_TIME     = TO_CHAR(SYSDATE,'HH24MISS')
 WHERE CMS_CATLG_ID = #{CMS_CATLG_ID}
